-- Server-side VAPID bootstrap. Private key is generated by the Edge Function and stored in Vault.
create or replace function public.trameli_store_vapid_config(
  p_public_key text,p_private_key text,p_subject text
) returns void
language plpgsql security definer set search_path to ''
as $$
declare v_id uuid;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if char_length(coalesce(p_public_key,''))<40
    or char_length(coalesce(p_private_key,''))<20
    or p_subject is null or char_length(p_subject)>300
  then raise exception 'invalid VAPID config' using errcode='22023'; end if;

  select id into v_id from vault.secrets where name='trameli_vapid_public_key';
  if v_id is null then perform vault.create_secret(p_public_key,'trameli_vapid_public_key','Public VAPID key for Pão Doce Web Push');
  else perform vault.update_secret(v_id,p_public_key,'trameli_vapid_public_key','Public VAPID key for Pão Doce Web Push'); end if;

  select id into v_id from vault.secrets where name='trameli_vapid_private_key';
  if v_id is null then perform vault.create_secret(p_private_key,'trameli_vapid_private_key','Private VAPID key for Pão Doce Web Push');
  else perform vault.update_secret(v_id,p_private_key,'trameli_vapid_private_key','Private VAPID key for Pão Doce Web Push'); end if;

  select id into v_id from vault.secrets where name='trameli_vapid_subject';
  if v_id is null then perform vault.create_secret(p_subject,'trameli_vapid_subject','VAPID contact subject for Pão Doce');
  else perform vault.update_secret(v_id,p_subject,'trameli_vapid_subject','VAPID contact subject for Pão Doce'); end if;
end $$;

revoke all on function public.trameli_store_vapid_config(text,text,text) from public,anon,authenticated;
grant execute on function public.trameli_store_vapid_config(text,text,text) to service_role;

create or replace function public.trameli_push_public_key()
returns text
language sql stable security definer set search_path to ''
as $$
  select decrypted_secret from vault.decrypted_secrets
  where name='trameli_vapid_public_key' limit 1;
$$;
revoke all on function public.trameli_push_public_key() from public,anon;
grant execute on function public.trameli_push_public_key() to authenticated;
